/** A tier's heading and its one muted orientation line. */
function TierHeading({
  id,
  title,
  children,
}: {
  id: string;
  title: string;
  children?: ReactNode;
}) {
  return (
    <div id={id} className="mt-16 first:mt-0">
      <Heading level={2}>{title}</Heading>
      {children ? (
        <Text className="mt-2 text-ploy-text-secondary">{children}</Text>
      ) : null}
    </div>
  );
}

/** One documented thing: a name, the rendered thing, its numbers, its rules. */
function Specimen({
  id,
  title,
  caption,
  use,
  avoid,
  scroll = false,
  children,
}: {
  id: string;
  title: string;
  caption: string;
  use?: string;
  avoid?: string;
  /** Wide content — a table, a tab row — scrolls rather than pushing the page. */
  scroll?: boolean;
  children: ReactNode;
}) {
  return (
    // `min-w-0`: a grid item defaults to `min-width: auto`, which refuses to
    // shrink below its content's intrinsic width — so a Table or a tab row
    // pushed its card to 538px inside a 390px column and took the page with it.
    // The specimen body scrolls instead, which is what Table already expects.
    <Card id={id} elevation="flat" className="flex min-w-0 flex-col gap-4">
      <Heading level={5}>{title}</Heading>
      {/* Only a specimen that is intrinsically wider than its column scrolls.
          Applied to all of them, the clipping context cut off the shadow a
          raised card exists to demonstrate. */}
      <div className={cn("min-w-0", scroll && "overflow-x-auto")}>
        {children}
      </div>
      <div className="mt-auto flex flex-col gap-1">
        <Text variant="small" className="text-ploy-text-secondary">
          {caption}
        </Text>
        {use ? (
          <Text>
            <strong>Use:</strong> {use}
          </Text>
        ) : null}
        {avoid ? (
          <Text>
            <strong>Avoid:</strong> {avoid}
          </Text>
        ) : null}
      </div>
    </Card>
  );
}

